from __future__ import annotations

import logging
import os
import re
import warnings
from typing import Iterable

_CONFIGURED = False

# Paths that poll frequently — keep out of access logs.
_QUIET_ACCESS_RE = re.compile(
    r'"(?:GET|HEAD)\s+/v1/(?:jobs/[^"\s]+|health|capabilities)(?:\?[^"\s]*)?\s+HTTP/',
    re.IGNORECASE,
)

_NOISY_WARNING_SUBSTR = (
    "max_new_tokens",
    "max_length",
    "Token indices sequence length",
    "sacremoses",
    "torch.utils._pytree",
    "resume_download",
    "use_auth_token",
)


class _QuietAccessFilter(logging.Filter):
    def filter(self, record: logging.LogRecord) -> bool:  # noqa: A003
        try:
            msg = record.getMessage()
        except Exception:
            return True
        return _QUIET_ACCESS_RE.search(msg) is None


class _DropNoisyWarningFilter(logging.Filter):
    def filter(self, record: logging.LogRecord) -> bool:  # noqa: A003
        try:
            msg = record.getMessage()
        except Exception:
            return True
        lower = msg.lower()
        return not any(s.lower() in lower for s in _NOISY_WARNING_SUBSTR)


def _silence_loggers(names: Iterable[str], level: int = logging.WARNING) -> None:
    for name in names:
        logging.getLogger(name).setLevel(level)


def configure_engine_logging(*, quiet_access: bool = True) -> None:
    """
    One-shot logging setup for `transub-engine serve`.
    Cuts FunASR/transformers/uvicorn noise so latest.log stays readable.
    """
    global _CONFIGURED
    if _CONFIGURED:
        return
    _CONFIGURED = True

    # Prefer no tqdm bars in captured stdout/stderr.
    os.environ.setdefault("TQDM_DISABLE", "1")
    os.environ.setdefault("FUNASR_DISABLE_UPDATE", "1")

    warnings.filterwarnings(
        "ignore",
        message=r".*max_new_tokens.*max_length.*",
        category=UserWarning,
    )
    warnings.filterwarnings(
        "ignore",
        message=r".*Token indices sequence length is longer.*",
        category=UserWarning,
    )
    warnings.filterwarnings(
        "ignore",
        message=r".*sacremoses.*",
        category=UserWarning,
    )
    warnings.filterwarnings(
        "ignore",
        message=r".*use_auth_token.*",
        category=FutureWarning,
    )

    root = logging.getLogger()
    if not root.handlers:
        logging.basicConfig(
            level=logging.INFO,
            format="%(levelname)s %(name)s: %(message)s",
        )
    else:
        root.setLevel(logging.INFO)

    _silence_loggers(
        (
            "transformers",
            "transformers.modeling_utils",
            "transformers.generation.utils",
            "transformers.tokenization_utils_base",
            "huggingface_hub",
            "httpx",
            "httpcore",
            "urllib3",
            "filelock",
            "modelscope",
            "jieba",
            "numba",
            "matplotlib",
        ),
        logging.ERROR,
    )
    _silence_loggers(("funasr", "funasr.auto", "funasr.utils"), logging.WARNING)
    _silence_loggers(("uvicorn.error",), logging.INFO)

    access = logging.getLogger("uvicorn.access")
    access.setLevel(logging.INFO)
    if quiet_access:
        access.addFilter(_QuietAccessFilter())

    # Also drop noisy records if they still reach the root via warnings logger.
    logging.getLogger("py.warnings").addFilter(_DropNoisyWarningFilter())
